// server.mjs
// خادم تطبيق عروض الأسعار — وحدات Node المدمجة فقط (http / fs / path / url)
// GET  /           → index.html
// POST /api/quote  → التحقق الصارم من المدخلات ثم حساب المجاميع

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT) || 3000;
const MAX_BODY_BYTES = 1_000_000; // حد معقول لحجم الجسم: 1 ميغابايت

const INVALID = { error: 'invalid' };

/* ---------------------------------- أدوات مساعدة ---------------------------------- */

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// أرقام فقط دون أي تحويل للنصوص أو null: عدد صحيح آمن ضمن المجال المطلوب
function isIntInRange(value, min, max) {
  return (
    typeof value === 'number' &&
    Number.isSafeInteger(value) &&
    value >= min &&
    value <= max
  );
}

function sendJson(res, status, payload) {
  if (res.writableEnded || res.destroyed) return;
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

/* --------------------------- التحقق من الطلب وحساب المجاميع --------------------------- */

function validateAndCompute(payload) {
  if (!isPlainObject(payload)) return null;

  const items = payload.items;
  const discountPercent = payload.discountPercent;
  const shippingCents = payload.shippingCents;

  // items: مصفوفة من 1 إلى 100 عنصرًا
  if (!Array.isArray(items) || items.length < 1 || items.length > 100) return null;
  // discountPercent: عدد صحيح من 0 إلى 100
  if (!isIntInRange(discountPercent, 0, 100)) return null;
  // shippingCents: عدد صحيح من 0 إلى 1000000
  if (!isIntInRange(shippingCents, 0, 1_000_000)) return null;

  const seenSkus = new Set();
  let subtotalCents = 0;

  for (const item of items) {
    if (!isPlainObject(item)) return null;

    const sku = item.sku;
    const unitPriceCents = item.unitPriceCents;
    const quantity = item.quantity;

    // sku: نص غير فارغ بعد trim ولا يتكرر
    if (typeof sku !== 'string') return null;
    const normalizedSku = sku.trim();
    if (normalizedSku.length === 0) return null;
    if (seenSkus.has(normalizedSku)) return null;
    seenSkus.add(normalizedSku);

    // unitPriceCents: عدد صحيح آمن من 0 إلى 10000000
    if (!isIntInRange(unitPriceCents, 0, 10_000_000)) return null;
    // quantity: عدد صحيح من 1 إلى 10000
    if (!isIntInRange(quantity, 1, 10_000)) return null;

    subtotalCents += unitPriceCents * quantity;
  }

  // مجموع الأسعار قبل الخصم يجب ألا يتجاوز 1000000000 سنت
  if (subtotalCents > 1_000_000_000) return null;

  // تقريب النصف للأعلى بعمليات صحيحة لتجنب أخطاء الفاصلة العائمة:
  // discountCents = floor((subtotalCents * discountPercent + 50) / 100)
  const discountCents = Math.floor((subtotalCents * discountPercent + 50) / 100);
  // الشحن يُضاف بعد الخصم ولا يدخل في حسابه
  const totalCents = subtotalCents - discountCents + shippingCents;

  // الحقول الأربعة فقط
  return { subtotalCents, discountCents, shippingCents, totalCents };
}

/* --------------------------------- معالج /api/quote --------------------------------- */

function handleQuote(req, res) {
  const chunks = [];
  let size = 0;
  let done = false; // تم الرد أو تجاوز الحد أو انقطع الاتصال

  const finish = (status, payload) => {
    if (done) return;
    done = true;
    sendJson(res, status, payload);
  };

  req.on('data', (chunk) => {
    if (done) return;
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      chunks.length = 0;
      finish(400, INVALID);
      req.resume(); // تجاهل بقية الجسم بدل قطع الاتصال ليعمل الرد 400
      return;
    }
    chunks.push(chunk);
  });

  req.on('aborted', () => { done = true; });
  req.on('close', () => { done = true; });
  req.on('error', () => { done = true; });

  req.on('end', () => {
    if (done) return;
    done = true;

    let parsed;
    try {
      parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch {
      return sendJson(res, 400, INVALID); // JSON معطوب
    }

    const result = validateAndCompute(parsed);
    if (result === null) return sendJson(res, 400, INVALID); // مدخلات مخالفة أو ناقصة

    return sendJson(res, 200, result);
  });
}

/* --------------------------------- الملفات الثابتة --------------------------------- */

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
};

function serveStatic(req, res, pathname) {
  const name = pathname === '/' || pathname === '' ? 'index.html' : pathname.replace(/^\/+/, '');

  // ملف واحد من جذر التطبيق فقط: لا مسارات فرعية ولا تجول في المسارات
  if (
    name.length === 0 ||
    name.includes('/') ||
    name.includes('\\') ||
    name.includes('..') ||
    name.includes('\0')
  ) {
    return sendJson(res, 404, { error: 'not_found' });
  }

  const contentType = MIME_TYPES[path.extname(name).toLowerCase()];
  if (!contentType) return sendJson(res, 404, { error: 'not_found' });

  fs.readFile(path.join(ROOT, name), (err, data) => {
    if (err) return sendJson(res, 404, { error: 'not_found' });
    if (res.writableEnded || res.destroyed) return;
    res.writeHead(200, {
      'Content-Type': contentType,
      'Content-Length': data.length,
      'Cache-Control': 'no-cache',
    });
    if (req.method === 'HEAD') return res.end();
    res.end(data);
  });
}

/* ------------------------------------ الموجّه ------------------------------------ */

async function route(req, res) {
  let pathname;
  try {
    pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
  } catch {
    return sendJson(res, 400, INVALID);
  }

  if (pathname === '/api/quote') {
    if (req.method !== 'POST') {
      res.setHeader('Allow', 'POST');
      return sendJson(res, 405, { error: 'invalid' });
    }
    return handleQuote(req, res);
  }

  if (req.method === 'GET' || req.method === 'HEAD') {
    return serveStatic(req, res, pathname);
  }

  return sendJson(res, 404, { error: 'invalid' });
}

const server = http.createServer((req, res) => {
  res.on('error', () => {});
  req.on('error', () => {});
  route(req, res).catch(() => {
    if (!res.writableEnded) sendJson(res, 500, { error: 'internal' });
  });
});

server.listen(PORT, () => {
  console.log(`✅ خادم عروض الأسعار يعمل على المنفذ ${PORT}`);
});

server.on('error', (err) => {
  console.error('❌ فشل تشغيل الخادم:', err.message);
  process.exit(1);
});

function shutdown() {
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

